-- ── routes (ex ps_rutas) ─────────────────────────────────────────────────
MERGE dbo.routes AS t USING (SELECT (SELECT id FROM dbo.clubs WHERE club_number = 6101) AS club, N'6101 01' AS code) AS s
  ON t.club_id = s.club AND t.code = s.code
WHEN NOT MATCHED AND s.club IS NOT NULL THEN INSERT (club_id, code, route_type_id, name, truck_size, is_active)
     VALUES (s.club, s.code, (SELECT id FROM dbo.route_types WHERE code = N'Home_Delivery'), N'Barranquilla Dual temp 2T', 2.0, 1);
MERGE dbo.routes AS t USING (SELECT (SELECT id FROM dbo.clubs WHERE club_number = 6101) AS club, N'6101 02' AS code) AS s
