-- ── route_prices (ex the tariff columns on ps_rutas) ─────────────────────
-- The legacy row held a column per tier: pallet_local, halfpallet_local,
-- `14pallet_local`, `14pallet_usd`. One row per tier here, so adding a tier
-- stops being an ALTER. A tier the legacy row left NULL produces no row.
MERGE dbo.route_prices AS t USING (SELECT (SELECT r.id FROM dbo.routes r JOIN dbo.clubs cl ON cl.id = r.club_id WHERE cl.club_number = 6101 AND r.code = N'6101 01') AS rid, N'FULL_PALLET' AS ut) AS s
  ON t.route_id = s.rid AND t.unit_type = s.ut
WHEN NOT MATCHED AND s.rid IS NOT NULL THEN INSERT (route_id, unit_type, price_local, price_usd, minimum_quantity) VALUES (s.rid, s.ut, 95000.0, 0, 4);
