MERGE dbo.country_payment_methods AS t USING (SELECT (SELECT id FROM dbo.countries WHERE iso2 = N'AW') AS cid, (SELECT id FROM dbo.payment_method_types WHERE code = N'US CASH') AS mid) AS s
  ON t.country_id = s.cid AND t.method_type_id = s.mid
WHEN NOT MATCHED AND s.cid IS NOT NULL AND s.mid IS NOT NULL THEN INSERT (country_id, method_type_id, tender_key, sort_order)
     VALUES (s.cid, s.mid, 11, 0);
